// 27-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (same speed as
// the pipeline, TRANSPOSED cone: one multiply+add per stage, independent of
// the number of stages -> shorter per-stage path -> shorter total path, higher
// Fmax).
module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:26];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd25 + 2*8'd1 + 5*xs[0] + 2*8'd2 + 5*xs[1] + 2*8'd3 + 5*xs[2] + 2*8'd4 + 5*xs[3] + 2*8'd5 + 5*xs[4] + 2*8'd6 + 5*xs[5] + 2*8'd7 + 5*xs[6] + 2*8'd8 + 5*xs[7] + 2*8'd9 + 5*xs[8] + 2*8'd10 + 5*xs[9] + 2*8'd11 + 5*xs[10] + 2*8'd12 + 5*xs[11] + 2*8'd13 + 5*xs[12] + 2*8'd14 + 5*xs[13] + 2*8'd15 + 5*xs[14] + 2*8'd16 + 5*xs[15] + 2*8'd17 + 5*xs[16] + 2*8'd18 + 5*xs[17] + 2*8'd19 + 5*xs[18] + 2*8'd20 + 5*xs[19] + 2*8'd21 + 5*xs[20] + 2*8'd22 + 5*xs[21] + 2*8'd23 + 5*xs[22] + 2*8'd24 + 5*xs[23] + 2*8'd25 + 5*xs[24] + 2*8'd26 + 5*xs[25] + 2*8'd27;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 27; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 27; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
